-- Robotics/Embedded/IoT pathway ("Vector Division") Act 15 -- "Edge to
-- Cloud" content, under world-vec-edge-to-cloud (already inserted by the
-- Acts 11-15 spine migration, 20260813180000). 1 campaign, 2 operations,
-- 12 missions (11 lessons + boss), following the same campaigns ->
-- operations -> missions -> dialogue -> objectives -> challenges -> hints
-- pattern as every other Act. No new ChallengeType needed -- reuses
-- story_dialogue, multiple_choice, drag_and_drop, investigation,
-- interactive_diagram, browser_simulation (generic console fallback) and
-- boss_encounter.
--
-- Continues Arc III ("Connect the Physical World"). Act 14 gave the
-- newly discovered controller population a real identity and a
-- connectivity plan and closed on: identity and a radio are not the same
-- as a working pipeline; reaching one device is not the same as seeing
-- all of them at once. Act 15 builds that pipeline. During its first
-- full fleet-wide test, Meridian Transit -- the very facility this whole
-- pathway started at in Act 1 -- drops its uplink entirely. The outage
-- itself resolves quickly and cleanly (edge buffering plus
-- store-and-forward means nothing was lost, only delayed), which is
-- deliberately NOT the real story: the boss mission's actual payload is
-- what the completed device registry shows once every provisioned
-- device finally reports in at once -- not one door, not one arm, but
-- thousands of matching controllers across Nexus, all quietly running
-- the same decades-old assumptions. This is the pathway's stated
-- biggest realization since Act 1: the crisis was never a
-- single-machine problem, it was always a fleet problem. Closes on the
-- pivot into Act 16, "Embedded Security": a fleet this reachable is also
-- a fleet this attackable.

insert into public.campaigns (id, world_id, slug, title, description, sort_order) values
  ('campaign-vec-edge-to-cloud', 'world-vec-edge-to-cloud', 'edge-to-cloud', '15A - Edge to Cloud', 'Learn the vocabulary of getting real data out of a real fleet -- telemetry pipelines, device shadow/twin concepts, command channels, cloud ingestion, time-series data, device registries, fleet management, rules engines, edge buffering, offline-first behavior and store-and-forward -- while Vector Division runs the first full fleet-wide telemetry test and discovers the crisis was never about one device.', 1);

insert into public.operations (id, campaign_id, slug, title, description, sort_order) values
  ('operation-vec-edge-to-cloud-1', 'campaign-vec-edge-to-cloud', 'the-first-full-test', 'The First Full Test', 'Telemetry pipelines, device shadow/twin concepts, command channels, cloud ingestion, time-series data and device registries.', 1),
  ('operation-vec-edge-to-cloud-2', 'campaign-vec-edge-to-cloud', 'a-fleet-problem', 'A Fleet Problem', 'Fleet management, rules engines, edge buffering, offline-first behavior, store-and-forward, and the first full fleet-wide test itself.', 2);

insert into public.missions (
  id, world_id, campaign_id, operation_id, slug, title, description, difficulty,
  character_ids, prerequisites, required_skills, lab, rewards, is_boss, sort_order
) values
  ('mission-vec-edge-to-cloud-01', 'world-vec-edge-to-cloud', 'campaign-vec-edge-to-cloud', 'operation-vec-edge-to-cloud-1', 'telemetry-pipelines', 'Telemetry Pipelines', 'Every controller Tomas provisioned in Act 14 can finally speak. Vector Division assembles the first real pipeline to carry a reading from a single device all the way to a dashboard Byte can actually watch.', 'beginner', ARRAY['imani','tomas','byte'], null, null, '{"type":"simulation","simulationId":"telemetry-pipelines-sim"}'::jsonb, '{"xp":220,"credits":25}'::jsonb, false, 1),
  ('mission-vec-edge-to-cloud-02', 'world-vec-edge-to-cloud', 'campaign-vec-edge-to-cloud', 'operation-vec-edge-to-cloud-1', 'device-shadow-twin', 'Device Shadow and Digital Twin', 'A device asleep to save power still needs to answer a question instantly. Tomas introduces the device shadow -- a cloud-side record of a device''s last known state, kept current whether or not the device itself is listening right now.', 'beginner', ARRAY['tomas','byte'], '{"requiredMissionIds":["mission-vec-edge-to-cloud-01"]}'::jsonb, null, '{"type":"simulation","simulationId":"device-shadow-twin-sim"}'::jsonb, '{"xp":220,"credits":30}'::jsonb, false, 2),
  ('mission-vec-edge-to-cloud-03', 'world-vec-edge-to-cloud', 'campaign-vec-edge-to-cloud', 'operation-vec-edge-to-cloud-1', 'command-channels', 'Command Channels at Fleet Scale', 'Telemetry flows out from thousands of devices at once. A command has to flow in, to exactly one of them, and prove it arrived. Tomas separates the two channels before the pipeline grows any further.', 'beginner', ARRAY['tomas','byte'], '{"requiredMissionIds":["mission-vec-edge-to-cloud-02"]}'::jsonb, null, '{"type":"simulation","simulationId":"command-channels-sim"}'::jsonb, '{"xp":230,"credits":30}'::jsonb, false, 3),
  ('mission-vec-edge-to-cloud-04', 'world-vec-edge-to-cloud', 'campaign-vec-edge-to-cloud', 'operation-vec-edge-to-cloud-1', 'cloud-ingestion', 'Cloud Ingestion at Scale', 'Ten thousand devices reporting at once do not arrive politely, one at a time. Byte walks through what actually absorbs that burst before a single value reaches storage.', 'beginner', ARRAY['byte','tomas'], '{"requiredMissionIds":["mission-vec-edge-to-cloud-03"]}'::jsonb, null, '{"type":"simulation","simulationId":"cloud-ingestion-sim"}'::jsonb, '{"xp":230,"credits":30}'::jsonb, false, 4),
  ('mission-vec-edge-to-cloud-05', 'world-vec-edge-to-cloud', 'campaign-vec-edge-to-cloud', 'operation-vec-edge-to-cloud-1', 'time-series-data', 'Time-Series Data', 'A telemetry stream is not a spreadsheet. Byte explains why a temperature reading taken every thirty seconds, forever, needs a different kind of database than a customer record ever did.', 'beginner', ARRAY['byte'], '{"requiredMissionIds":["mission-vec-edge-to-cloud-04"]}'::jsonb, null, '{"type":"simulation","simulationId":"time-series-data-sim"}'::jsonb, '{"xp":240,"credits":35}'::jsonb, false, 5),
  ('mission-vec-edge-to-cloud-06', 'world-vec-edge-to-cloud', 'campaign-vec-edge-to-cloud', 'operation-vec-edge-to-cloud-1', 'device-registries', 'The Device Registry', 'Every device Tomas provisioned in Act 14 needed one more thing: a single authoritative record of its existence. As the pipeline test ramps up, that registry starts filling in, live, for the first time.', 'beginner', ARRAY['tomas','byte','imani'], '{"requiredMissionIds":["mission-vec-edge-to-cloud-05"]}'::jsonb, null, '{"type":"simulation","simulationId":"device-registries-sim"}'::jsonb, '{"xp":240,"credits":35}'::jsonb, false, 6),
  ('mission-vec-edge-to-cloud-07', 'world-vec-edge-to-cloud', 'campaign-vec-edge-to-cloud', 'operation-vec-edge-to-cloud-2', 'fleet-management', 'Managing a Fleet, Not a Device', 'Imani stops asking about one controller at a time. Vector Division needs to group, filter and command thousands of them together, or the pipeline test will drown in individual questions.', 'beginner', ARRAY['imani','tomas'], '{"requiredMissionIds":["mission-vec-edge-to-cloud-06"]}'::jsonb, null, '{"type":"simulation","simulationId":"fleet-management-sim"}'::jsonb, '{"xp":250,"credits":35}'::jsonb, false, 7),
  ('mission-vec-edge-to-cloud-08', 'world-vec-edge-to-cloud', 'campaign-vec-edge-to-cloud', 'operation-vec-edge-to-cloud-2', 'rules-engines', 'Rules Engines', 'Nobody can watch ten thousand dashboards by hand. Byte sets up a rules engine to watch the fleet''s telemetry continuously and flag the moment any device says something that matters.', 'beginner', ARRAY['byte','tomas'], '{"requiredMissionIds":["mission-vec-edge-to-cloud-07"]}'::jsonb, null, '{"type":"simulation","simulationId":"rules-engines-sim"}'::jsonb, '{"xp":250,"credits":40}'::jsonb, false, 8),
  ('mission-vec-edge-to-cloud-09', 'world-vec-edge-to-cloud', 'campaign-vec-edge-to-cloud', 'operation-vec-edge-to-cloud-2', 'edge-buffering', 'Edge Buffering', 'Every provisioned device now holds a small local buffer of its own. Tomas explains why -- a link can fail for a hundred reasons a device cannot control, and the data collected during that gap should not simply vanish.', 'beginner', ARRAY['tomas','byte'], '{"requiredMissionIds":["mission-vec-edge-to-cloud-08"]}'::jsonb, null, '{"type":"simulation","simulationId":"edge-buffering-sim"}'::jsonb, '{"xp":260,"credits":40}'::jsonb, false, 9),
  ('mission-vec-edge-to-cloud-10', 'world-vec-edge-to-cloud', 'campaign-vec-edge-to-cloud', 'operation-vec-edge-to-cloud-2', 'offline-first-behavior', 'Designing Offline-First', 'Tomas asks the player to stop treating disconnection as an emergency. At fleet scale it is the normal condition, and the pipeline has to be designed around it from the start, not patched afterward.', 'beginner', ARRAY['tomas'], '{"requiredMissionIds":["mission-vec-edge-to-cloud-09"]}'::jsonb, null, '{"type":"simulation","simulationId":"offline-first-behavior-sim"}'::jsonb, '{"xp":260,"credits":40}'::jsonb, false, 10),
  ('mission-vec-edge-to-cloud-11', 'world-vec-edge-to-cloud', 'campaign-vec-edge-to-cloud', 'operation-vec-edge-to-cloud-2', 'store-and-forward', 'Store-and-Forward', 'Edge buffering and offline-first design combine into one working pattern: hold data locally, detect reconnection, forward everything collected in the gap, then resume the live stream exactly where it left off.', 'beginner', ARRAY['tomas','byte'], '{"requiredMissionIds":["mission-vec-edge-to-cloud-10"]}'::jsonb, null, '{"type":"simulation","simulationId":"store-and-forward-sim"}'::jsonb, '{"xp":270,"credits":45}'::jsonb, false, 11),
  ('mission-vec-edge-to-cloud-12', 'world-vec-edge-to-cloud', 'campaign-vec-edge-to-cloud', 'operation-vec-edge-to-cloud-2', 'the-broken-uplink', 'The Broken Uplink', 'The first full fleet-wide telemetry test goes live across every provisioned facility -- and Meridian Transit''s uplink drops out entirely. Diagnose the outage, confirm nothing was actually lost, and read what the completed registry finally shows once every device reports in at once.', 'boss', ARRAY['imani','tomas','byte'], '{"requiredMissionIds":["mission-vec-edge-to-cloud-11"]}'::jsonb, null, '{"type":"simulation","simulationId":"the-broken-uplink-boss-sim"}'::jsonb, '{"xp":1150,"credits":240,"badgeIds":["the-broken-uplink"],"skillXp":{"robotics_fundamentals":150}}'::jsonb, true, 12);

insert into public.dialogue_lines (mission_id, sort_order, character_id, text) values
  ('mission-vec-edge-to-cloud-01', 1, 'imani', 'Every controller Tomas provisioned in Act 14 can finally speak. Today we find out whether we can actually hear all of them at once. First full fleet-wide telemetry test starts now.'),
  ('mission-vec-edge-to-cloud-01', 2, 'tomas', 'A telemetry pipeline is not one piece of software. It is a chain: the device collects a reading, a gateway relays it outward, an ingestion service accepts it, a storage layer keeps it, and a dashboard finally puts it in front of a person. Break any one link and the reading never arrives, even if the device sent it perfectly.'),
  ('mission-vec-edge-to-cloud-01', 3, 'byte', 'I have never had a live view of more than eighty-two devices at once. Today that number changes by several orders of magnitude, assuming the pipeline holds.'),
  ('mission-vec-edge-to-cloud-01', 4, 'imani', 'Then let us build it correctly the first time. Learn the chain before we turn it on.'),

  ('mission-vec-edge-to-cloud-02', 1, 'tomas', 'A device shadow is a record, kept in the cloud, of a device''s last known state -- what it last reported, what it was last told to do. It exists because a device asleep to save power cannot always answer a question the instant somebody asks it.'),
  ('mission-vec-edge-to-cloud-02', 2, 'byte', 'Query the shadow and I get an answer immediately, even if the actual device has not checked in for ten minutes. Query the device directly and I might wait ten minutes for nothing.'),
  ('mission-vec-edge-to-cloud-02', 3, 'tomas', 'The shadow is not the truth. It is the best known approximation of the truth, current as of the last time the device actually spoke. Treat the difference carelessly and the pipeline will lie to someone eventually.'),

  ('mission-vec-edge-to-cloud-03', 1, 'tomas', 'Telemetry flows outward, one direction, from every device to whoever is watching. A command channel is the opposite: inward, addressed to one specific device, and it has to prove the device actually received it.'),
  ('mission-vec-edge-to-cloud-03', 2, 'byte', 'A telemetry channel can drop a single reading and nobody notices, because another one arrives in thirty seconds. A command channel cannot drop the one message telling a device to do something. It needs an acknowledgment, or a way to know the command never landed.'),
  ('mission-vec-edge-to-cloud-03', 3, 'tomas', 'Build both channels the same way and you get a fleet that reports beautifully and cannot reliably be told anything at all.'),

  ('mission-vec-edge-to-cloud-04', 1, 'byte', 'Ten thousand devices do not politely queue up and report one at a time. They arrive in bursts, all at once, especially right after a reconnect. Whatever accepts that traffic first has to absorb the burst without losing anything or falling over.'),
  ('mission-vec-edge-to-cloud-04', 2, 'tomas', 'That is cloud ingestion''s entire job: sit between the noisy, bursty world of real devices and the orderly, steady world storage and processing expect. A message broker holds the burst, a stream processor drains it at a pace it can actually handle.'),
  ('mission-vec-edge-to-cloud-04', 3, 'byte', 'Skip that layer and write every device directly into storage, and the first real burst will not test the pipeline. It will break it.'),

  ('mission-vec-edge-to-cloud-05', 1, 'byte', 'A temperature reading taken every thirty seconds, forever, is not a normal database row. It is one point in an enormous, ever-growing sequence, always indexed by time, almost always queried by a time range.'),
  ('mission-vec-edge-to-cloud-05', 2, 'byte', 'A relational database can technically hold that. It was never built to hold billions of timestamped rows efficiently, or to answer "show me the last hour" instantly once the table gets large. Time-series storage is built for exactly that shape of question.'),
  ('mission-vec-edge-to-cloud-05', 3, 'tomas', 'Every dashboard we are about to build runs on time-series queries. Get this layer wrong and every other layer above it inherits the slowdown.'),

  ('mission-vec-edge-to-cloud-06', 1, 'tomas', 'Every device I provisioned in Act 14 got a real identity. The registry is where that identity actually lives -- one authoritative record per device, tying its identity to whatever metadata matters: location, model, firmware version, last-seen time.'),
  ('mission-vec-edge-to-cloud-06', 2, 'byte', 'As the pipeline test ramps up, I am watching the registry populate in real time. Every device that successfully reports in for the first time adds one more confirmed entry.'),
  ('mission-vec-edge-to-cloud-06', 3, 'imani', 'How many entries does a full population actually look like?'),
  ('mission-vec-edge-to-cloud-06', 4, 'byte', 'I do not know yet. That is exactly what today is going to tell us.'),

  ('mission-vec-edge-to-cloud-07', 1, 'imani', 'I am done asking Byte about one controller at a time. Give me a group -- every device in a wing, every device on a given firmware version, every device that has not reported in an hour -- and let me act on the group at once.'),
  ('mission-vec-edge-to-cloud-07', 2, 'tomas', 'That is fleet management: treating devices as a queryable population instead of a list of individuals. Group them by whatever property matters, then read, command or update the whole group in one operation instead of thousands of separate ones.'),
  ('mission-vec-edge-to-cloud-07', 3, 'imani', 'Fleet management does not replace device management, then. It sits on top of it.'),
  ('mission-vec-edge-to-cloud-07', 4, 'tomas', 'Exactly. Somewhere underneath every group action is still one device, one identity, one connection at a time. Fleet tools just stop making a human do that part by hand.'),

  ('mission-vec-edge-to-cloud-08', 1, 'byte', 'Nobody on this team can watch ten thousand telemetry streams by eye. A rules engine watches instead -- a standing set of conditions, evaluated continuously against every incoming reading, that fires an action automatically when one of them matches.'),
  ('mission-vec-edge-to-cloud-08', 2, 'tomas', 'If temperature exceeds a threshold, alert. If a device has not reported in fifteen minutes, flag it as possibly offline. The rule does not need a human present to notice. It needs to exist before the condition happens.'),
  ('mission-vec-edge-to-cloud-08', 3, 'byte', 'I already have one running quietly in the background of this Act. It fired forty minutes ago, on a condition none of us set up on purpose.'),

  ('mission-vec-edge-to-cloud-09', 1, 'tomas', 'Every device I provisioned carries a small local buffer now -- flash memory set aside specifically to hold readings that have not been sent yet. It is not a workaround. It is the honest acknowledgment that a link can fail for reasons the device cannot control.'),
  ('mission-vec-edge-to-cloud-09', 2, 'byte', 'Radio interference, a dead gateway, a facility-wide outage -- none of that is the device''s fault, and none of it should mean the data collected during the gap simply disappears.'),
  ('mission-vec-edge-to-cloud-09', 3, 'tomas', 'Edge buffering means a disconnected device keeps doing its job. It just stops being able to tell anyone about it, temporarily.'),

  ('mission-vec-edge-to-cloud-10', 1, 'tomas', 'Stop treating disconnection as an emergency. At the scale we are about to run, some fraction of ten thousand devices is disconnected at literally every moment, for completely ordinary reasons. That has to be the default assumption, not the exception.'),
  ('mission-vec-edge-to-cloud-10', 2, 'tomas', 'Offline-first means every piece of firmware is designed to keep functioning correctly with no connection at all, and to treat a working uplink as a bonus, not a requirement.'),
  ('mission-vec-edge-to-cloud-10', 3, 'byte', 'Design it the other way -- assume connectivity and patch around the gaps -- and every gap becomes an incident. Design it offline-first, and most gaps become invisible.'),

  ('mission-vec-edge-to-cloud-11', 1, 'tomas', 'Edge buffering and offline-first design are not two separate features. Put together correctly, they become one pattern: store-and-forward. Hold data locally while disconnected. Detect the moment the link returns. Forward everything collected in the gap, in order. Then resume the live stream exactly where it left off.'),
  ('mission-vec-edge-to-cloud-11', 2, 'byte', 'Done correctly, a disconnection becomes a delay, not a loss. The receiving end simply sees the backlog arrive a little late, followed immediately by the live stream catching up.'),
  ('mission-vec-edge-to-cloud-11', 3, 'tomas', 'Every provisioned device in this test is running that exact pattern right now. We are about to find out whether it holds up outside a lab.'),

  ('mission-vec-edge-to-cloud-12', 1, 'imani', 'Full fleet-wide test, live, across every facility we provisioned. Byte, status.'),
  ('mission-vec-edge-to-cloud-12', 2, 'byte', 'Every device is reporting, except one location. Meridian Transit -- the same facility this entire Act started at -- dropped off the pipeline nine minutes ago. Zero telemetry, zero acknowledgments, uplink completely dark.'),
  ('mission-vec-edge-to-cloud-12', 3, 'tomas', 'Do not panic yet. A dropped uplink at this scale is not automatically a disaster. Check what actually failed before assuming the worst.'),
  ('mission-vec-edge-to-cloud-12', 4, 'byte', 'Uplink is back. Gateway rebooted itself after a routine power fluctuation, nothing malicious, nothing structural. And the backlog just landed -- every reading Meridian Transit''s devices collected during the gap, arriving now, in order, timestamped for exactly when it was recorded.'),
  ('mission-vec-edge-to-cloud-12', 5, 'tomas', 'That is store-and-forward doing exactly what it was built to do. The uplink itself was a minor, ordinary failure, recovered cleanly because the edge firmware buffered and forwarded what it collected while disconnected.'),
  ('mission-vec-edge-to-cloud-12', 6, 'byte', 'The registry just crossed full population. This is the first complete picture I have ever had of anything in this pathway. Not one door. Not one arm. Thousands of matching controllers across Nexus, all quietly running the same decades-old assumptions -- and for the first time, I can see all of them at once.'),
  ('mission-vec-edge-to-cloud-12', 7, 'imani', 'Say what that actually means, Byte. Not the count. What it means.'),
  ('mission-vec-edge-to-cloud-12', 8, 'byte', 'Thousands of disconnected devices reveal that the crisis was never a single-machine problem. It was always a fleet problem.'),
  ('mission-vec-edge-to-cloud-12', 9, 'imani', 'A fleet this size, all reachable at once, is also a fleet this size all attackable at once, if Vector Division does not secure it first. That is not tomorrow''s problem. Byte, hold what you are seeing. We start on it next.');

insert into public.objectives (id, mission_id, sort_order, title, description) values
  ('mission-vec-edge-to-cloud-01-o1', 'mission-vec-edge-to-cloud-01', 1, 'Order the pipeline', 'Order the telemetry pipeline from a single device reading to a dashboard.'),
  ('mission-vec-edge-to-cloud-01-o2', 'mission-vec-edge-to-cloud-01', 2, 'Explain the point of it', 'State what a telemetry pipeline accomplishes that a single device reporting to a single screen cannot.'),

  ('mission-vec-edge-to-cloud-02-o1', 'mission-vec-edge-to-cloud-02', 1, 'Define the shadow', 'Choose the accurate description of a device shadow.'),
  ('mission-vec-edge-to-cloud-02-o2', 'mission-vec-edge-to-cloud-02', 2, 'Sort shadow vs live queries', 'Sort each action into querying the shadow or querying the live device directly.'),

  ('mission-vec-edge-to-cloud-03-o1', 'mission-vec-edge-to-cloud-03', 1, 'Tell the channels apart', 'Choose the accurate distinction between a command channel and a telemetry channel.'),
  ('mission-vec-edge-to-cloud-03-o2', 'mission-vec-edge-to-cloud-03', 2, 'Explain the acknowledgment', 'Find the evidence explaining why command delivery has to be confirmed.'),

  ('mission-vec-edge-to-cloud-04-o1', 'mission-vec-edge-to-cloud-04', 1, 'Order ingestion', 'Order the path a burst of readings takes through cloud ingestion.'),
  ('mission-vec-edge-to-cloud-04-o2', 'mission-vec-edge-to-cloud-04', 2, 'Explain the buffering layer', 'State why cloud ingestion needs a buffering layer instead of writing devices straight into storage.'),

  ('mission-vec-edge-to-cloud-05-o1', 'mission-vec-edge-to-cloud-05', 1, 'Define time-series data', 'Choose the accurate description of time-series data.'),
  ('mission-vec-edge-to-cloud-05-o2', 'mission-vec-edge-to-cloud-05', 2, 'Sort the fits', 'Sort each example into a good fit or a poor fit for time-series storage.'),

  ('mission-vec-edge-to-cloud-06-o1', 'mission-vec-edge-to-cloud-06', 1, 'Define the registry', 'Choose the accurate description of the device registry''s role.'),
  ('mission-vec-edge-to-cloud-06-o2', 'mission-vec-edge-to-cloud-06', 2, 'Prove it is live', 'Find the evidence proving the registry reflects real devices actually reporting in.'),

  ('mission-vec-edge-to-cloud-07-o1', 'mission-vec-edge-to-cloud-07', 1, 'Tell fleet from device management', 'Choose the accurate distinction between fleet management and device management.'),
  ('mission-vec-edge-to-cloud-07-o2', 'mission-vec-edge-to-cloud-07', 2, 'Sort the tasks', 'Sort each task into single-device management or fleet-level management.'),

  ('mission-vec-edge-to-cloud-08-o1', 'mission-vec-edge-to-cloud-08', 1, 'Define a rules engine', 'Choose the accurate description of a rules engine.'),
  ('mission-vec-edge-to-cloud-08-o2', 'mission-vec-edge-to-cloud-08', 2, 'Find what it caught', 'Find the evidence showing the rules engine caught something with no human watching.'),

  ('mission-vec-edge-to-cloud-09-o1', 'mission-vec-edge-to-cloud-09', 1, 'Define edge buffering', 'Choose the accurate description of edge buffering.'),
  ('mission-vec-edge-to-cloud-09-o2', 'mission-vec-edge-to-cloud-09', 2, 'Confirm it is real', 'Find the evidence proving the provisioned devices are actually equipped for edge buffering.'),

  ('mission-vec-edge-to-cloud-10-o1', 'mission-vec-edge-to-cloud-10', 1, 'Define offline-first', 'Choose the accurate description of offline-first design.'),
  ('mission-vec-edge-to-cloud-10-o2', 'mission-vec-edge-to-cloud-10', 2, 'Sort the design choices', 'Sort each design choice into offline-first or online-required.'),

  ('mission-vec-edge-to-cloud-11-o1', 'mission-vec-edge-to-cloud-11', 1, 'Define store-and-forward', 'Choose the accurate description of the store-and-forward pattern.'),
  ('mission-vec-edge-to-cloud-11-o2', 'mission-vec-edge-to-cloud-11', 2, 'Order the sequence', 'Order the store-and-forward sequence as a disconnection happens and then resolves.'),

  ('mission-vec-edge-to-cloud-12-o1', 'mission-vec-edge-to-cloud-12', 1, 'Diagnose the uplink', 'Determine what actually caused Meridian Transit''s uplink to drop.'),
  ('mission-vec-edge-to-cloud-12-o2', 'mission-vec-edge-to-cloud-12', 2, 'Confirm nothing was lost', 'Prove the disconnection produced a delay, not a loss, using the recovered backlog.'),
  ('mission-vec-edge-to-cloud-12-o3', 'mission-vec-edge-to-cloud-12', 3, 'Confirm the registry', 'Confirm the device registry is now fully populated as every provisioned device reports in.'),
  ('mission-vec-edge-to-cloud-12-o4', 'mission-vec-edge-to-cloud-12', 4, 'Name the real discovery', 'Having confirmed the uplink was ordinary and nothing was lost, state what the completed registry actually reveals.');

insert into public.challenges (id, objective_id, sort_order, type, prompt, content, completion_conditions) values
  ('mission-vec-edge-to-cloud-01-o1-c1', 'mission-vec-edge-to-cloud-01-o1', 1, 'interactive_diagram', 'Order the telemetry pipeline from a single sensor reading to a person watching a dashboard.', '{"diagramId":"telemetry-pipeline","hotspots":[{"id":"device","label":"Device","explanation":"Collects a reading from the physical world."},{"id":"gateway","label":"Gateway","explanation":"Relays the reading outward from the local network toward the cloud."},{"id":"ingestion","label":"Ingestion service","explanation":"Accepts incoming readings at scale and hands them off for processing."},{"id":"storage","label":"Storage","explanation":"Keeps the reading so it can be queried later."},{"id":"dashboard","label":"Dashboard","explanation":"Displays the stored data to a person watching it."}],"task":"Order the pipeline from device to dashboard."}'::jsonb, '{"correctOrderIds":["device","gateway","ingestion","storage","dashboard"]}'::jsonb),
  ('mission-vec-edge-to-cloud-01-o2-c1', 'mission-vec-edge-to-cloud-01-o2', 1, 'multiple_choice', 'What does a telemetry pipeline actually accomplish that a single device reporting to a single screen cannot?', '{"question":"What does a telemetry pipeline actually accomplish that a single device reporting to a single screen cannot?","options":[{"id":"a","text":"Nothing, it is just a longer version of the same thing"},{"id":"b","text":"It lets thousands of devices report continuously, at scale, with each stage handling a different job -- relaying, absorbing bursts, storing and displaying -- so no single stage has to do everything"},{"id":"c","text":"It replaces the need for a device to collect real data"},{"id":"d","text":"It only matters for devices that use Wi-Fi"}]}'::jsonb, '{"correctOptionId":"b"}'::jsonb),

  ('mission-vec-edge-to-cloud-02-o1-c1', 'mission-vec-edge-to-cloud-02-o1', 1, 'multiple_choice', 'A device shadow is best described as...', '{"question":"A device shadow is best described as...","options":[{"id":"a","text":"A duplicate physical device kept as a backup"},{"id":"b","text":"A cloud-side record of a device''s last known state, current as of the last time the device actually reported in"},{"id":"c","text":"A live, guaranteed-accurate mirror of the device updated instantly"},{"id":"d","text":"A security log of every command ever sent to the device"}]}'::jsonb, '{"correctOptionId":"b"}'::jsonb),
  ('mission-vec-edge-to-cloud-02-o2-c1', 'mission-vec-edge-to-cloud-02-o2', 1, 'drag_and_drop', 'Sort each action into querying the shadow or querying the live device directly.', '{"items":[{"id":"i1","text":"Ask what temperature a sensor last reported, and get an instant answer even if the sensor is currently asleep"},{"id":"i2","text":"Send a command directly to a device and wait for it to actually execute right now"},{"id":"i3","text":"Check a device''s last-known firmware version without waking it up"},{"id":"i4","text":"Request a fresh reading taken at this exact moment"}],"targets":[{"id":"shadow","label":"Query the shadow"},{"id":"live","label":"Query the live device"}]}'::jsonb, '{"correctMapping":{"i1":"shadow","i2":"live","i3":"shadow","i4":"live"}}'::jsonb),

  ('mission-vec-edge-to-cloud-03-o1-c1', 'mission-vec-edge-to-cloud-03-o1', 1, 'multiple_choice', 'A command channel differs from a telemetry channel in that...', '{"question":"A command channel differs from a telemetry channel in that...","options":[{"id":"a","text":"They are the same channel, just relabeled"},{"id":"b","text":"Telemetry flows outward from every device to any listener; a command flows inward, addressed to one specific device, and needs a way to confirm it actually arrived"},{"id":"c","text":"Commands are always sent over Wi-Fi and telemetry never is"},{"id":"d","text":"A telemetry channel requires acknowledgment and a command channel does not"}]}'::jsonb, '{"correctOptionId":"b"}'::jsonb),
  ('mission-vec-edge-to-cloud-03-o2-c1', 'mission-vec-edge-to-cloud-03-o2', 1, 'investigation', 'Which evidence explains why command delivery has to be confirmed?', '{"evidence":[{"id":"e1","label":"Design note","detail":"A missed telemetry reading is followed by another one within seconds, at negligible cost"},{"id":"e2","label":"Design note","detail":"A missed command means a device never receives an instruction it was specifically supposed to act on, with no automatic retry unless something confirms delivery"},{"id":"e3","label":"Facilities note","detail":"Commands and telemetry are transmitted using the same radio hardware"}],"question":"Which evidence explains why command delivery has to be confirmed?"}'::jsonb, '{"requiredEvidenceIds":["e2"]}'::jsonb),

  ('mission-vec-edge-to-cloud-04-o1-c1', 'mission-vec-edge-to-cloud-04-o1', 1, 'interactive_diagram', 'Order the path a burst of readings takes through cloud ingestion.', '{"diagramId":"cloud-ingestion-path","hotspots":[{"id":"gateway","label":"Devices and gateways","explanation":"Send readings toward the cloud, all at once, especially after a reconnect."},{"id":"broker","label":"Message broker / queue","explanation":"Accepts the burst and holds it, absorbing the spike."},{"id":"processor","label":"Stream processor","explanation":"Drains the queue at a pace downstream systems can actually handle."},{"id":"storage","label":"Storage","explanation":"Receives processed data, ready to be queried."}],"task":"Order ingestion from raw burst to stored data."}'::jsonb, '{"correctOrderIds":["gateway","broker","processor","storage"]}'::jsonb),
  ('mission-vec-edge-to-cloud-04-o2-c1', 'mission-vec-edge-to-cloud-04-o2', 1, 'multiple_choice', 'Why does cloud ingestion need a buffering layer, like a message broker, instead of writing every device straight into storage?', '{"question":"Why does cloud ingestion need a buffering layer, like a message broker, instead of writing every device straight into storage?","options":[{"id":"a","text":"It does not, direct writes are always fine"},{"id":"b","text":"A burst of thousands of devices reporting at once can exceed what storage can accept directly; a broker decouples the noisy arrival pattern from the steady pace storage and processing expect"},{"id":"c","text":"Brokers are required by every cloud provider''s terms of service"},{"id":"d","text":"Storage is always faster than any broker"}]}'::jsonb, '{"correctOptionId":"b"}'::jsonb),

  ('mission-vec-edge-to-cloud-05-o1-c1', 'mission-vec-edge-to-cloud-05-o1', 1, 'multiple_choice', 'Time-series data is best described as...', '{"question":"Time-series data is best described as...","options":[{"id":"a","text":"Any data stored in a database"},{"id":"b","text":"Data structured as an ordered sequence of values, each tied to a timestamp, almost always queried by time range rather than by individual record"},{"id":"c","text":"Data that only updates once a year"},{"id":"d","text":"A synonym for any log file"}]}'::jsonb, '{"correctOptionId":"b"}'::jsonb),
  ('mission-vec-edge-to-cloud-05-o2-c1', 'mission-vec-edge-to-cloud-05-o2', 1, 'drag_and_drop', 'Sort each example into a good fit or a poor fit for time-series storage.', '{"items":[{"id":"t1","text":"A sensor''s temperature reading recorded every thirty seconds, forever"},{"id":"t2","text":"A customer''s billing address, updated rarely, queried by customer id"},{"id":"t3","text":"A device''s telemetry stream, queried mostly by \"show me the last hour\""},{"id":"t4","text":"A one-time device provisioning record, queried by device id"}],"targets":[{"id":"timeseries","label":"Good fit for time-series"},{"id":"other","label":"Poor fit for time-series"}]}'::jsonb, '{"correctMapping":{"t1":"timeseries","t2":"other","t3":"timeseries","t4":"other"}}'::jsonb),

  ('mission-vec-edge-to-cloud-06-o1-c1', 'mission-vec-edge-to-cloud-06-o1', 1, 'multiple_choice', 'The device registry''s role is best described as...', '{"question":"The device registry''s role is best described as...","options":[{"id":"a","text":"A place to store firmware source code"},{"id":"b","text":"The single authoritative record tying every device''s identity to its metadata -- location, model, firmware version, last-seen time"},{"id":"c","text":"A backup copy of the telemetry database"},{"id":"d","text":"A list of every command ever issued"}]}'::jsonb, '{"correctOptionId":"b"}'::jsonb),
  ('mission-vec-edge-to-cloud-06-o2-c1', 'mission-vec-edge-to-cloud-06-o2', 1, 'investigation', 'Which evidence proves the registry reflects real devices actually reporting in, not just a static list?', '{"evidence":[{"id":"e1","label":"Registry log","detail":"Entries increase in real time, one per device, exactly as each provisioned device successfully completes its first report through the new pipeline"},{"id":"e2","label":"Facilities note","detail":"The registry was created as an empty table before the test began"},{"id":"e3","label":"Byte''s note","detail":"Dashboards existed before the registry did"}],"question":"Which evidence proves the registry reflects real devices actually reporting in, not just a static list?"}'::jsonb, '{"requiredEvidenceIds":["e1"]}'::jsonb),

  ('mission-vec-edge-to-cloud-07-o1-c1', 'mission-vec-edge-to-cloud-07-o1', 1, 'multiple_choice', 'Fleet management differs from device management in that...', '{"question":"Fleet management differs from device management in that...","options":[{"id":"a","text":"Fleet management replaces the need to manage individual devices"},{"id":"b","text":"Fleet management treats devices as a queryable, groupable population, letting one operation act on many devices at once instead of requiring one action per device"},{"id":"c","text":"Fleet management only applies to devices using the same protocol"},{"id":"d","text":"There is no real difference"}]}'::jsonb, '{"correctOptionId":"b"}'::jsonb),
  ('mission-vec-edge-to-cloud-07-o2-c1', 'mission-vec-edge-to-cloud-07-o2', 1, 'drag_and_drop', 'Sort each task into single-device management or fleet-level management.', '{"items":[{"id":"g1","text":"Check one specific door controller''s current firmware version"},{"id":"g2","text":"Find every device on a specific outdated firmware version, across every facility"},{"id":"g3","text":"Push a configuration update to every sensor that has not reported in an hour"},{"id":"g4","text":"Read one controller''s raw diagnostic output directly"}],"targets":[{"id":"single","label":"Single-device management"},{"id":"fleet","label":"Fleet-level management"}]}'::jsonb, '{"correctMapping":{"g1":"single","g2":"fleet","g3":"fleet","g4":"single"}}'::jsonb),

  ('mission-vec-edge-to-cloud-08-o1-c1', 'mission-vec-edge-to-cloud-08-o1', 1, 'multiple_choice', 'A rules engine is best described as...', '{"question":"A rules engine is best described as...","options":[{"id":"a","text":"A person manually reviewing every dashboard"},{"id":"b","text":"A standing set of conditions evaluated continuously against incoming data, that fires an action automatically the moment one condition matches"},{"id":"c","text":"A one-time validation check run when a device is first provisioned"},{"id":"d","text":"A firmware update mechanism"}]}'::jsonb, '{"correctOptionId":"b"}'::jsonb),
  ('mission-vec-edge-to-cloud-08-o2-c1', 'mission-vec-edge-to-cloud-08-o2', 1, 'investigation', 'Which evidence shows the rules engine caught something without a human watching?', '{"evidence":[{"id":"e1","label":"Rules engine log","detail":"Condition \"no report received in fifteen minutes\" fired automatically for a specific device group, no human present when it triggered"},{"id":"e2","label":"Dashboard note","detail":"A human operator was watching the dashboard the entire time"},{"id":"e3","label":"Facilities note","detail":"The rules engine was still being configured at that time"}],"question":"Which evidence shows the rules engine caught something without a human watching?"}'::jsonb, '{"requiredEvidenceIds":["e1"]}'::jsonb),

  ('mission-vec-edge-to-cloud-09-o1-c1', 'mission-vec-edge-to-cloud-09-o1', 1, 'multiple_choice', 'Edge buffering means...', '{"question":"Edge buffering means...","options":[{"id":"a","text":"A device discards any reading it cannot immediately send"},{"id":"b","text":"A device holds readings it collects locally, in its own flash memory, whenever it cannot currently reach the network, instead of losing them"},{"id":"c","text":"A cloud service buffers data on behalf of every device"},{"id":"d","text":"Only gateways are capable of buffering, never individual devices"}]}'::jsonb, '{"correctOptionId":"b"}'::jsonb),
  ('mission-vec-edge-to-cloud-09-o2-c1', 'mission-vec-edge-to-cloud-09-o2', 1, 'investigation', 'Which evidence shows the newly provisioned devices are actually equipped for edge buffering, not just theoretically capable of it?', '{"evidence":[{"id":"e1","label":"Firmware build note","detail":"Every provisioned device''s firmware image includes a dedicated flash region reserved specifically for buffering unsent readings"},{"id":"e2","label":"Facilities note","detail":"Some of these devices are physically difficult to access"},{"id":"e3","label":"Power log","detail":"Buffering slightly increases a device''s average power draw"}],"question":"Which evidence shows the newly provisioned devices are actually equipped for edge buffering, not just theoretically capable of it?"}'::jsonb, '{"requiredEvidenceIds":["e1"]}'::jsonb),

  ('mission-vec-edge-to-cloud-10-o1-c1', 'mission-vec-edge-to-cloud-10-o1', 1, 'multiple_choice', 'Offline-first design means...', '{"question":"Offline-first design means...","options":[{"id":"a","text":"A device that only works when disconnected"},{"id":"b","text":"Firmware designed to function correctly with no connection at all, treating a working uplink as a bonus rather than a requirement"},{"id":"c","text":"A device that refuses to connect to the network on purpose"},{"id":"d","text":"A backup plan used only during emergencies"}]}'::jsonb, '{"correctOptionId":"b"}'::jsonb),
  ('mission-vec-edge-to-cloud-10-o2-c1', 'mission-vec-edge-to-cloud-10-o2', 1, 'drag_and_drop', 'Sort each design choice into offline-first or online-required.', '{"items":[{"id":"d1","text":"A device logs every reading locally regardless of connection status, and sends when it can"},{"id":"d2","text":"A device blocks and retries endlessly if it cannot reach the cloud before taking its next reading"},{"id":"d3","text":"A device''s core sensing loop runs identically whether connected or not"},{"id":"d4","text":"A device requires a live cloud round-trip before it will report a valid reading at all"}],"targets":[{"id":"offlinefirst","label":"Offline-first"},{"id":"onlinerequired","label":"Online-required"}]}'::jsonb, '{"correctMapping":{"d1":"offlinefirst","d2":"onlinerequired","d3":"offlinefirst","d4":"onlinerequired"}}'::jsonb),

  ('mission-vec-edge-to-cloud-11-o1-c1', 'mission-vec-edge-to-cloud-11-o1', 1, 'multiple_choice', 'Store-and-forward is best described as...', '{"question":"Store-and-forward is best described as...","options":[{"id":"a","text":"A way to permanently discard data collected while disconnected"},{"id":"b","text":"The pattern of holding data locally while disconnected, detecting reconnection, then forwarding the full backlog before resuming the live stream"},{"id":"c","text":"A protocol exclusively for command channels"},{"id":"d","text":"A cloud-only feature with no edge component"}]}'::jsonb, '{"correctOptionId":"b"}'::jsonb),
  ('mission-vec-edge-to-cloud-11-o2-c1', 'mission-vec-edge-to-cloud-11-o2', 1, 'interactive_diagram', 'Order the store-and-forward sequence as a disconnection happens and then resolves.', '{"diagramId":"store-and-forward-sequence","hotspots":[{"id":"buffer","label":"Buffer locally","explanation":"Device buffers readings locally because the uplink is unavailable."},{"id":"detect","label":"Detect reconnection","explanation":"Device detects that the connection has returned."},{"id":"forward","label":"Forward the backlog","explanation":"Device forwards the full buffered backlog, in order."},{"id":"resume","label":"Resume live stream","explanation":"Device resumes live streaming from the current moment."}],"task":"Order the sequence from disconnection to full recovery."}'::jsonb, '{"correctOrderIds":["buffer","detect","forward","resume"]}'::jsonb),

  ('mission-vec-edge-to-cloud-12-o1-c1', 'mission-vec-edge-to-cloud-12-o1', 1, 'investigation', 'What actually caused Meridian Transit''s uplink to drop?', '{"evidence":[{"id":"e1","label":"Gateway log","detail":"Meridian Transit''s gateway lost power for eleven seconds during a routine facility power fluctuation, then rebooted and reconnected automatically -- no configuration change, no external access attempt"},{"id":"e2","label":"Security audit","detail":"No login attempts, no credential use, no unusual authentication activity anywhere near Meridian Transit during the outage window"},{"id":"e3","label":"Facilities schedule","detail":"Unrelated maintenance work was happening in a different wing of Meridian Transit that day"}],"question":"What actually caused Meridian Transit''s uplink to drop?"}'::jsonb, '{"requiredEvidenceIds":["e1"]}'::jsonb),
  ('mission-vec-edge-to-cloud-12-o2-c1', 'mission-vec-edge-to-cloud-12-o2', 1, 'investigation', 'Which evidence proves the outage produced a delay, not a permanent loss?', '{"evidence":[{"id":"e1","label":"Buffer audit","detail":"Every Meridian Transit device''s edge buffer held exactly the readings collected during the nine-minute gap, with correct original timestamps, and forwarded the full backlog immediately upon reconnection"},{"id":"e2","label":"Bandwidth log","detail":"Reconnection briefly spiked network usage as backlog data arrived"},{"id":"e3","label":"Registry note","detail":"Meridian Transit''s device count was unchanged before and after the outage"}],"question":"Which evidence proves the outage produced a delay, not a permanent loss?"}'::jsonb, '{"requiredEvidenceIds":["e1"]}'::jsonb),
  ('mission-vec-edge-to-cloud-12-o3-c1', 'mission-vec-edge-to-cloud-12-o3', 1, 'investigation', 'Which evidence confirms the device registry is now fully populated?', '{"evidence":[{"id":"e1","label":"Registry snapshot","detail":"Entry count now matches the full population of newly provisioned controllers across every facility in this test, each with a confirmed first-contact timestamp -- populated live, in full, for the first time"},{"id":"e2","label":"Registry snapshot","detail":"Entry count matches only the eighty-two devices reachable at the start of Act 14"},{"id":"e3","label":"Registry note","detail":"Entries still only cover Meridian Transit"}],"question":"Which evidence confirms the device registry is now fully populated?"}'::jsonb, '{"requiredEvidenceIds":["e1"]}'::jsonb),
  ('mission-vec-edge-to-cloud-12-o4-c1', 'mission-vec-edge-to-cloud-12-o4', 1, 'boss_encounter', 'Having confirmed the uplink was an ordinary failure and nothing was lost, state what the completed registry actually reveals.', '{"stages":[{"objectiveRef":"mission-vec-edge-to-cloud-12-o1","label":"Diagnose the uplink"},{"objectiveRef":"mission-vec-edge-to-cloud-12-o2","label":"Confirm nothing was lost"},{"objectiveRef":"mission-vec-edge-to-cloud-12-o3","label":"Confirm the registry"}],"task":"State the real discovery in one sentence: thousands of disconnected devices reveal that the crisis was never a single-machine problem. It was always a fleet problem."}'::jsonb, '{"requiredObjectiveIds":["mission-vec-edge-to-cloud-12-o1","mission-vec-edge-to-cloud-12-o2","mission-vec-edge-to-cloud-12-o3"],"allCorrect":true}'::jsonb);

insert into public.hints (challenge_id, tier, text, xp_cost, sort_order) values
  ('mission-vec-edge-to-cloud-01-o1-c1', 'orientation', 'Nothing further along the chain can run before power and a raw reading exist first.', 10, 1),
  ('mission-vec-edge-to-cloud-01-o1-c1', 'concept', 'Each stage hands off to exactly one next stage: collect, relay, accept at scale, store, display.', 20, 2),
  ('mission-vec-edge-to-cloud-01-o1-c1', 'solution', 'Device, then gateway, then ingestion, then storage, then dashboard.', 30, 3),
  ('mission-vec-edge-to-cloud-01-o2-c1', 'orientation', 'Think about what happens once thousands of devices are reporting, not just one.', 10, 1),
  ('mission-vec-edge-to-cloud-01-o2-c1', 'solution', 'A pipeline lets many devices report at scale, with each stage handling one job so no single piece has to do everything.', 20, 2),

  ('mission-vec-edge-to-cloud-02-o1-c1', 'orientation', 'A shadow is not the device itself -- it is a record about the device.', 10, 1),
  ('mission-vec-edge-to-cloud-02-o1-c1', 'solution', 'A device shadow is a cloud-side record of the device''s last known state, current as of its last real report.', 20, 2),
  ('mission-vec-edge-to-cloud-02-o2-c1', 'orientation', 'Ask whether the action needs the device to respond right now, or just needs the last known answer.', 10, 1),
  ('mission-vec-edge-to-cloud-02-o2-c1', 'concept', 'Shadow queries are instant and use stale-but-recent data. Live queries wait on the actual device and get a fresh answer.', 20, 2),
  ('mission-vec-edge-to-cloud-02-o2-c1', 'solution', 'Shadow: i1 (last reported temperature), i3 (last-known firmware version). Live: i2 (execute a command now), i4 (fresh reading right now).', 30, 3),

  ('mission-vec-edge-to-cloud-03-o1-c1', 'orientation', 'Ask which direction each channel travels, and what happens if one message on it goes missing.', 10, 1),
  ('mission-vec-edge-to-cloud-03-o1-c1', 'solution', 'Telemetry flows outward from many devices; a command flows inward to one device and needs confirmation of arrival.', 20, 2),
  ('mission-vec-edge-to-cloud-03-o2-c1', 'orientation', 'Compare what is lost when one telemetry reading disappears versus when one command disappears.', 10, 1),
  ('mission-vec-edge-to-cloud-03-o2-c1', 'solution', 'e2: a missed command means an instruction the device was supposed to act on simply never arrives, with no automatic retry unless delivery is confirmed.', 20, 2),

  ('mission-vec-edge-to-cloud-04-o1-c1', 'orientation', 'Data has to be accepted before it can be processed, and processed before it is safely stored.', 10, 1),
  ('mission-vec-edge-to-cloud-04-o1-c1', 'concept', 'Devices produce a bursty, uneven flow. A broker absorbs the burst. A processor smooths it out before storage.', 20, 2),
  ('mission-vec-edge-to-cloud-04-o1-c1', 'solution', 'Devices and gateways, then the message broker, then the stream processor, then storage.', 30, 3),
  ('mission-vec-edge-to-cloud-04-o2-c1', 'orientation', 'Think about what happens the instant thousands of devices reconnect at the same moment.', 10, 1),
  ('mission-vec-edge-to-cloud-04-o2-c1', 'solution', 'A broker decouples the bursty arrival of device data from the steady pace storage and processing can actually handle.', 20, 2),

  ('mission-vec-edge-to-cloud-05-o1-c1', 'orientation', 'Ask what almost every query against this kind of data actually asks for: a time range, or a single record.', 10, 1),
  ('mission-vec-edge-to-cloud-05-o1-c1', 'solution', 'Time-series data is an ordered sequence of timestamped values, almost always queried by time range.', 20, 2),
  ('mission-vec-edge-to-cloud-05-o2-c1', 'orientation', 'Ask whether the data grows continuously over time and is queried by time range, or stays small and is queried by an id.', 10, 1),
  ('mission-vec-edge-to-cloud-05-o2-c1', 'concept', 'Continuous, ever-growing, time-range-queried data fits time-series storage. Small, id-queried, rarely-changing data does not need it.', 20, 2),
  ('mission-vec-edge-to-cloud-05-o2-c1', 'solution', 'Good fit: t1 (repeating temperature reading), t3 (telemetry queried by last hour). Poor fit: t2 (billing address by customer id), t4 (one-time provisioning record by device id).', 30, 3),

  ('mission-vec-edge-to-cloud-06-o1-c1', 'orientation', 'The registry does not store data the device produces. It stores facts about the device itself.', 10, 1),
  ('mission-vec-edge-to-cloud-06-o1-c1', 'solution', 'The registry is the single authoritative record of every device''s identity and metadata.', 20, 2),
  ('mission-vec-edge-to-cloud-06-o2-c1', 'orientation', 'Look for evidence tying registry growth directly to devices actually reporting, not just to the table existing.', 10, 1),
  ('mission-vec-edge-to-cloud-06-o2-c1', 'solution', 'e1: entries increase in real time, one per device, exactly as each device completes its first report -- proof it reflects real activity.', 20, 2),

  ('mission-vec-edge-to-cloud-07-o1-c1', 'orientation', 'Fleet management does not remove individual devices from the picture -- it changes how many of them you can act on at once.', 10, 1),
  ('mission-vec-edge-to-cloud-07-o1-c1', 'solution', 'Fleet management treats devices as a groupable population, letting one operation act on many devices instead of one at a time.', 20, 2),
  ('mission-vec-edge-to-cloud-07-o2-c1', 'orientation', 'Ask whether the task names one specific device, or a property shared by many devices.', 10, 1),
  ('mission-vec-edge-to-cloud-07-o2-c1', 'concept', 'A single named device or its raw output is device-level. A group defined by a shared property, acted on together, is fleet-level.', 20, 2),
  ('mission-vec-edge-to-cloud-07-o2-c1', 'solution', 'Single-device: g1 (one controller''s firmware version), g4 (one controller''s raw output). Fleet-level: g2 (every device on a firmware version), g3 (every device that missed its report window).', 30, 3),

  ('mission-vec-edge-to-cloud-08-o1-c1', 'orientation', 'A rules engine does not wait for a person to notice something. It watches continuously on its own.', 10, 1),
  ('mission-vec-edge-to-cloud-08-o1-c1', 'solution', 'A rules engine evaluates standing conditions continuously and fires an action automatically the moment one matches.', 20, 2),
  ('mission-vec-edge-to-cloud-08-o2-c1', 'orientation', 'Look for a log entry that fired on its own, with no operator involved at the time.', 10, 1),
  ('mission-vec-edge-to-cloud-08-o2-c1', 'solution', 'e1: the "no report in fifteen minutes" condition fired automatically with no human present -- proof the engine caught it unattended.', 20, 2),

  ('mission-vec-edge-to-cloud-09-o1-c1', 'orientation', 'Buffering is about what the device does with data it cannot currently send, not about discarding it.', 10, 1),
  ('mission-vec-edge-to-cloud-09-o1-c1', 'solution', 'Edge buffering means a device holds unsent readings locally in flash instead of losing them when it cannot reach the network.', 20, 2),
  ('mission-vec-edge-to-cloud-09-o2-c1', 'orientation', 'Look for evidence about what is actually built into the firmware, not evidence about physical access or power cost.', 10, 1),
  ('mission-vec-edge-to-cloud-09-o2-c1', 'solution', 'e1: every provisioned device''s firmware image includes a dedicated flash region reserved specifically for buffering unsent readings.', 20, 2),

  ('mission-vec-edge-to-cloud-10-o1-c1', 'orientation', 'Offline-first is about how the device behaves normally, not about a special emergency mode.', 10, 1),
  ('mission-vec-edge-to-cloud-10-o1-c1', 'solution', 'Offline-first firmware functions correctly with no connection at all, treating a working uplink as a bonus, not a requirement.', 20, 2),
  ('mission-vec-edge-to-cloud-10-o2-c1', 'orientation', 'Ask whether the device''s core behavior depends on the cloud being reachable right now.', 10, 1),
  ('mission-vec-edge-to-cloud-10-o2-c1', 'concept', 'Offline-first choices keep working with no connection. Online-required choices block or fail without one.', 20, 2),
  ('mission-vec-edge-to-cloud-10-o2-c1', 'solution', 'Offline-first: d1 (logs locally regardless of connection), d3 (sensing loop runs the same either way). Online-required: d2 (blocks and retries endlessly), d4 (requires a live round-trip to report at all).', 30, 3),

  ('mission-vec-edge-to-cloud-11-o1-c1', 'orientation', 'Store-and-forward combines two ideas already covered this Act into one working pattern.', 10, 1),
  ('mission-vec-edge-to-cloud-11-o1-c1', 'solution', 'Store-and-forward holds data locally while disconnected, then forwards the full backlog and resumes live streaming once reconnected.', 20, 2),
  ('mission-vec-edge-to-cloud-11-o2-c1', 'orientation', 'Nothing can be forwarded before it has been buffered, and nothing can be forwarded before reconnection is actually detected.', 10, 1),
  ('mission-vec-edge-to-cloud-11-o2-c1', 'concept', 'The sequence follows the disconnection itself: buffer while down, notice it is back up, clear the backlog, then go live again.', 20, 2),
  ('mission-vec-edge-to-cloud-11-o2-c1', 'solution', 'Buffer locally, then detect reconnection, then forward the backlog, then resume the live stream.', 30, 3),

  ('mission-vec-edge-to-cloud-12-o1-c1', 'orientation', 'Rule out the evidence that only proves absence of an attack, and find the evidence that actually explains the cause.', 10, 1),
  ('mission-vec-edge-to-cloud-12-o1-c1', 'solution', 'e1: a routine power fluctuation caused an eleven-second outage and automatic reboot -- an ordinary hardware event, nothing malicious.', 20, 2),
  ('mission-vec-edge-to-cloud-12-o2-c1', 'orientation', 'Look for the evidence that directly ties the buffer''s contents to what was actually forwarded after reconnection.', 10, 1),
  ('mission-vec-edge-to-cloud-12-o2-c1', 'solution', 'e1: the buffer audit shows every reading collected during the gap was forwarded with correct original timestamps -- a delay, not a loss.', 20, 2),
  ('mission-vec-edge-to-cloud-12-o3-c1', 'orientation', 'Look for the snapshot that matches the full provisioned population, not a partial or outdated count.', 10, 1),
  ('mission-vec-edge-to-cloud-12-o3-c1', 'solution', 'e1: the registry entry count now matches the full population across every facility in the test, each with a confirmed first-contact timestamp.', 20, 2),
